SELECT s.issue_key, s.status, s.status_category
FROM issue_state_known_at(TIMESTAMP '2017-12-09 02:07', TIMESTAMP '2017-12-09 02:07') s
WHERE s.issue_key IN ('INDY-493','INDY-740','INDY-741','INDY-742','INDY-739');

SELECT l.src, l.relation, l.dst, l.valid_from, l.valid_to
FROM links_at(TIMESTAMP '2019-06-13 04:43') l
WHERE l.src = 'MXS-2499' OR l.dst = 'MXS-2499';

SELECT * FROM issue_state_known_at(TIMESTAMP '2019-06-13 04:43', TIMESTAMP '2019-06-13 04:43')
WHERE issue_key IN (
  SELECT src FROM links_at(TIMESTAMP '2019-06-13 04:43') WHERE dst = 'MXS-2499'
  UNION
  SELECT dst FROM links_at(TIMESTAMP '2019-06-13 04:43') WHERE src = 'MXS-2499'
);

SELECT COUNT(*) AS n
FROM issue_state_at(TIMESTAMP '2015-06-20 18:59')
WHERE status IN ('Confirmed', 'In Progress', 'In Review', 'Stalled');

SELECT issue_key, status, status_category
FROM issue_state_at(TIMESTAMP '2014-01-07 17:11')
WHERE issue_key IN ('SEC-1179','SEC-962','SEC-1181');

SELECT s.issue_key, s.status, s.status_category, s.assignee, s.status_since
FROM issue_state_known_at(TIMESTAMP '2013-06-07 00:21', TIMESTAMP '2013-06-07 00:21') s
ORDER BY s.issue_key;

SELECT s.issue_key, s.status, s.status_category, s.assignee, s.status_since
FROM issue_state_known_at(TIMESTAMP '2013-06-07 00:21', TIMESTAMP '2013-06-07 00:21') s
WHERE s.issue_key IN ('SEC-493', 'SEC-516');

SELECT issue_key, status, status_category, status_since
FROM issue_state_known_at(TIMESTAMP '2018-09-18 16:02', TIMESTAMP '2018-09-20 21:11')
WHERE issue_key = 'MXS-2057';

SELECT s.issue_key, s.status, s.status_category
FROM issue_state_known_at(TIMESTAMP '2020-11-24 05:35', TIMESTAMP '2020-11-24 05:35') s
WHERE s.issue_key IN ('INDY-1343','INDY-1638','INDY-1607','INDY-2214','INDY-1737','INDY-1717');

SELECT status, status_category, status_since
FROM issue_state_at(TIMESTAMP '2020-08-20 01:29')
WHERE issue_key = 'INDY-1594';

SELECT
 (SELECT COUNT(*) FROM issue_state_at(TIMESTAMP '2019-12-07 08:37') s JOIN issues i ON i.key = s.issue_key WHERE i.project='INDY' AND s.status IN ('Code Review','Customer Validation','Design','In Progress','To Test')) AS current_belief_total,
 (SELECT COUNT(*) FROM issue_state_known_at(TIMESTAMP '2019-12-07 08:37', TIMESTAMP '2019-12-07 08:37') s JOIN issues i ON i.key = s.issue_key WHERE i.project='INDY' AND s.status IN ('Code Review','Customer Validation','Design','In Progress','To Test')) AS known_total;

SELECT count(*) AS n
FROM issue_state_at(TIMESTAMP '2013-10-24 17:33') s
WHERE s.status IN ('In Progress','Investigating','Waiting for Feedback');
